-- Restore 60 Mongolian-bank questions that the external sync overwrote with rewritten variants
-- (different numbers, answers or choices) between 5 and 10 Oct 2026, before sync-external-questions
-- stopped writing to this bank on 11 Oct. Originals come from the variant engine's own pre-write
-- backups (SAT Platform/sat-parser data/import/backup_*.json, earliest copy of each question), which
-- match its source files. Ids and codes are unchanged, so student answers stay linked. The variants
-- stay in intl_questions. Questions that only gained an explanation or a figure are not touched.
-- A row is only restored if nothing has changed it since 11 Oct; skipped rows are listed in a NOTICE.
DO $restore$
DECLARE n int; skipped text;
BEGIN
  CREATE TEMP TABLE restore_originals (id uuid PRIMARY KEY, code text, data jsonb) ON COMMIT DROP;

  UPDATE public.questions q SET (question_text, answer, multiple_choice_options, rationale, passage_text, alternate_answers, question_image_url, choice_images, video_url, has_figure, figure_type, figure_description, figure_svg, difficulty_level) = (
    SELECT r.question_text, r.answer, r.multiple_choice_options, r.rationale, r.passage_text, r.alternate_answers, r.question_image_url, r.choice_images, r.video_url, r.has_figure, r.figure_type, r.figure_description, r.figure_svg, r.difficulty_level
    FROM jsonb_populate_record(NULL::public.questions, o.data) r)
  FROM restore_originals o
  WHERE q.id = o.id AND q.updated_at < '2026-10-11T02:00:00Z';
  GET DIAGNOSTICS n = ROW_COUNT;

  SELECT string_agg(o.code, ', ' ORDER BY o.code) INTO skipped FROM restore_originals o
  WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id = o.id AND q.updated_at >= now() - interval '1 minute');
  RAISE NOTICE '0072: restored % of 60 questions to their originals. Not restored (changed since 11 Oct or missing): %', n, coalesce(skipped, 'none');
END $restore$;
